import{_ as d,o as a,c as r,a2 as l}from"./chunks/framework.mRCPFc5l.js";const f=JSON.parse('{"title":"伏笔洋葱层分类","description":"","frontmatter":{},"headers":[],"relativePath":"叙事与伏笔/伏笔洋葱层分类.md","filePath":"叙事与伏笔/伏笔洋葱层分类.md","lastUpdated":1786679977000}'),e={name:"叙事与伏笔/伏笔洋葱层分类.md"};function s(h,t,i,o,y,n){return a(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="伏笔洋葱层分类" tabindex="-1">伏笔洋葱层分类 <a class="header-anchor" href="#伏笔洋葱层分类" aria-label="Permalink to &quot;伏笔洋葱层分类&quot;">​</a></h1><p>本文档统一编号并维护世界观中的未解之谜。编号顺序不代表揭晓顺序；状态随设定更新同步维护。</p><h2 id="一、表层伏笔-福瑞世界可见的异常" tabindex="-1">一、表层伏笔（福瑞世界可见的异常） <a class="header-anchor" href="#一、表层伏笔-福瑞世界可见的异常" aria-label="Permalink to &quot;一、表层伏笔（福瑞世界可见的异常）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>编号</th><th>谜面</th><th>状态</th><th>真相所在</th></tr></thead><tbody><tr><td>F-01</td><td>地脉的本质——神明警示：&quot;那是大地的伤口，而且并没有愈合。&quot;</td><td>已揭晓</td><td><a href="./../中层/世界/地脉与魔法" class="layer-link" data-layer="中层">地脉与魔法</a></td></tr><tr><td>F-02</td><td>甲族灭绝的原因无人记载，似乎被刻意抹除。</td><td>已揭晓</td><td><a href="./../中层/历史/正传历史" class="layer-link" data-layer="中层">正传历史</a></td></tr><tr><td>F-03</td><td>龙族曾存在于文献与史书中，却不知何时忽然消失。</td><td>已揭晓</td><td><a href="./../中层/世界/龙族真相" class="layer-link" data-layer="中层">龙族真相</a></td></tr><tr><td>F-04</td><td>猫族的存在——目击者最多，但普通人难以见到。</td><td>未揭晓</td><td><a href="./../表层/种族/猫族" class="layer-link" data-layer="表层">猫族</a></td></tr><tr><td>F-05</td><td>&quot;焰种&quot;只存在于古代文献的只言片语中，天穹破碎后曾出现。</td><td>已揭晓</td><td><a href="./../中层/世界/太空巨构" class="layer-link" data-layer="中层">太空巨构</a></td></tr><tr><td>F-06</td><td>大陆上古环形山的来历。</td><td>已揭晓</td><td><a href="./../中层/历史/前传超算纪元" class="layer-link" data-layer="中层">前传超算纪元</a></td></tr><tr><td>F-07</td><td>六边形沙漠近百年来持续升温，终成无活物可生存的无人区。</td><td>已揭晓</td><td><a href="./../中层/历史/正传历史" class="layer-link" data-layer="中层">正传历史</a></td></tr><tr><td>F-08</td><td>精灵族经历上一次大变故后大多隐居，变故原因成谜。</td><td>已揭晓</td><td><a href="./../中层/世界/特殊地点" class="layer-link" data-layer="中层">特殊地点</a></td></tr><tr><td>F-09</td><td>天穹破碎事件——天空为何碎裂，神环为何在那时显现。</td><td>已揭晓</td><td><a href="./../中层/世界/太空巨构" class="layer-link" data-layer="中层">太空巨构</a></td></tr><tr><td>F-10</td><td>拉斯塔童年被&quot;没有尾巴的巨龙&quot;所救，她寻龙多年无果。</td><td>已揭晓</td><td><a href="./../中层/人物/古斯塔夫" class="layer-link" data-layer="中层">古斯塔夫</a></td></tr><tr><td>F-11</td><td>狼族少年的来历——出生不明，被人在山洞中发现。</td><td>未揭晓</td><td><a href="./../中层/人物/狼族少年" class="layer-link" data-layer="中层">狼族少年</a></td></tr><tr><td>F-12</td><td>狼族的&quot;天真纯善&quot;总让人觉得有些不自然。</td><td>已揭晓</td><td><a href="./../中层/世界/神机谋划" class="layer-link" data-layer="中层">神机谋划</a></td></tr><tr><td>F-13</td><td>狮族的&quot;异域科技&quot;与橙黄色高能结晶从何而来。</td><td>已揭晓</td><td><a href="./../中层/历史/正传历史" class="layer-link" data-layer="中层">正传历史</a></td></tr></tbody></table><h2 id="二、中层伏笔-隐藏真相层面的谜团" tabindex="-1">二、中层伏笔（隐藏真相层面的谜团） <a class="header-anchor" href="#二、中层伏笔-隐藏真相层面的谜团" aria-label="Permalink to &quot;二、中层伏笔（隐藏真相层面的谜团）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>编号</th><th>谜面</th><th>状态</th><th>真相所在</th></tr></thead><tbody><tr><td>F-14</td><td>神机所掌握神权的真实位阶——她的力量，似乎远比表面展现的更加深不可测。</td><td>未揭晓</td><td><a href="./../中层/人物/神机" class="layer-link" data-layer="中层">神机</a></td></tr><tr><td>F-15</td><td>精灵族副院长艾莉芙的身份并不简单——她与神机之间，似乎存在着某种不为人知的联系。</td><td>未揭晓</td><td><a href="./../中层/人物/艾莉芙" class="layer-link" data-layer="中层">艾莉芙</a></td></tr><tr><td>F-16</td><td>狐族&quot;全雌、后代只会是狐族&quot;的繁衍特性背后，似乎还有更深一层的原因。</td><td>未揭晓</td><td><a href="./../中层/人物/神机" class="layer-link" data-layer="中层">神机</a></td></tr><tr><td>F-17</td><td>太空中的克隆仓库维系着某种脆弱的平衡——若这平衡被打破，会发生什么？</td><td>未揭晓</td><td><a href="./../中层/世界/神机谋划" class="layer-link" data-layer="中层">神机谋划</a></td></tr><tr><td>F-18</td><td>小白狼家乡的深坑——毁灭神权残余与未消散的意识存于其中，是特殊的空间节点。</td><td>未揭晓</td><td><a href="./../底层/人物/上位毁灭神" class="layer-link" data-layer="底层">上位毁灭神</a></td></tr><tr><td>F-19</td><td>&quot;小狼时代&quot;：毁灭神消失后至狼国和平化之间的过渡期与&quot;小狼&quot;领袖。</td><td>待定（构思中）</td><td><a href="./../表层/种族/狼族" class="layer-link" data-layer="表层">狼族</a></td></tr><tr><td>F-20</td><td>上位毁灭神权的&quot;根&quot;埋藏于狼族起源或核心区域，是神机布局的一环。</td><td>未揭晓</td><td><a href="./../底层/人物/上位毁灭神" class="layer-link" data-layer="底层">上位毁灭神</a></td></tr><tr><td>F-21</td><td>指引狐族少女唤醒神明的&quot;那位神明&quot;是谁。</td><td>已揭晓</td><td><a href="./../中层/历史/正传历史" class="layer-link" data-layer="中层">正传历史</a></td></tr><tr><td>F-22</td><td>前传时期进入基底层深处的那些&quot;人&quot;——他们如今在哪里，又是否还会回来？</td><td>未揭晓</td><td><a href="./../中层/世界/地脉与魔法" class="layer-link" data-layer="中层">地脉与魔法</a></td></tr><tr><td>F-23</td><td>维斯塔黑化支线——&quot;赤色暴君&quot;是否会把支线并入主线、复活神机。</td><td>未揭晓（支线）</td><td><a href="./维斯塔黑化" class="layer-link" data-layer="底层">维斯塔黑化</a></td></tr></tbody></table><h2 id="三、底层伏笔-元规则层面的谜团" tabindex="-1">三、底层伏笔（元规则层面的谜团） <a class="header-anchor" href="#三、底层伏笔-元规则层面的谜团" aria-label="Permalink to &quot;三、底层伏笔（元规则层面的谜团）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>编号</th><th>谜面</th><th>状态</th><th>真相所在</th></tr></thead><tbody><tr><td>F-24</td><td>玩家为何能够存档、读档、操作时间线——其能力的本质。</td><td>未揭晓</td><td><a href="./../底层/规则/叙事与玩家" class="layer-link" data-layer="底层">叙事与玩家</a></td></tr><tr><td>F-25</td><td>未来与过去、时间线是否真实存在。</td><td>未揭晓</td><td><a href="./../底层/规则/神权体系" class="layer-link" data-layer="底层">神权体系</a></td></tr><tr><td>F-26</td><td>神权使用代价的具体判定规则——初代变化神制定的细节至今未明。</td><td>未揭晓</td><td><a href="./../底层/规则/神权体系" class="layer-link" data-layer="底层">神权体系</a></td></tr><tr><td>F-27</td><td>初代创造神的起源与创造目的。</td><td>未揭晓</td><td><a href="./../底层/人物/初代创造神" class="layer-link" data-layer="底层">初代创造神</a></td></tr><tr><td>F-28</td><td>基底层中扭曲人类的命运与执念。</td><td>未揭晓</td><td><a href="./../底层/规则/基底层与现实世界" class="layer-link" data-layer="底层">基底层与现实世界</a></td></tr><tr><td>F-29</td><td>真结局的最终选择——在世界的最底层，还存在着最后一个选项：没有人知道选择它之后，一切会变成什么样。</td><td>未揭晓（剧情选择）</td><td><a href="./../中层/历史/正传历史" class="layer-link" data-layer="中层">正传历史</a></td></tr><tr><td>F-30</td><td>叙事逻辑与作者的存在——神机推算出了它，却无法直接证明。</td><td>未揭晓</td><td><a href="./../底层/规则/叙事与玩家" class="layer-link" data-layer="底层">叙事与玩家</a></td></tr></tbody></table><h2 id="维护规则" tabindex="-1">维护规则 <a class="header-anchor" href="#维护规则" aria-label="Permalink to &quot;维护规则&quot;">​</a></h2><ul><li>新增伏笔：登记编号、谜面、所在层级、关联文件。</li><li>揭晓伏笔：状态改为&quot;已揭晓&quot;并填入真相所在文件链接。</li><li>禁止删除旧记录，仅更新状态。</li></ul>',10)])])}const u=d(e,[["render",s]]);export{f as __pageData,u as default};
